#!/bin/sh
# Generated by the Scalar SDK Generator. Edits here are overwritten on the next generation.
#
# Installs the standalone galaxy executable from this project's GitHub releases:
#
#   curl -fsSL https://github.com/scalar/galaxy-cli/releases/latest/download/install.sh | bash
#
# Re-running it upgrades an existing install in place, and so does `galaxy upgrade`: both download
# the archive built for this machine, verify it against the release's `checksums.txt`, and replace
# the executable with one atomic rename.
#
# Options, read from the environment, or the version as the first argument (`| bash -s -- 1.2.3`):
#   GALAXY_VERSION         release to install, such as 1.2.3 (default: the latest release)
#   GALAXY_INSTALL_DIR     directory to install into (default: $HOME/.local/bin)
#   GALAXY_NO_MODIFY_PATH  set to leave shell startup files alone and print the PATH line instead
#
# When the install directory is not on PATH, the script adds it for new shells by appending one line to
# the startup file of your shell (zsh's .zshrc, ~/.bashrc, the login file bash reads on macOS, fish's
# conf.d, or ~/.profile for other POSIX shells), and says which file it changed.
#
# POSIX sh rather than bash, so `| sh` works as well as `| bash` on a system with no bash at all.
set -eu

BIN='galaxy'
REPO='scalar/galaxy-cli'

# Everything runs from `main`, called on the script's last line. A download cut off partway leaves the
# shell holding a function it never reaches the call for, so a truncated script does nothing rather
# than running whichever commands happened to arrive.
main() {
  version="${1:-${GALAXY_VERSION:-latest}}"
  install_dir="${GALAXY_INSTALL_DIR:-${HOME:?HOME is not set; set GALAXY_INSTALL_DIR instead}/.local/bin}"

  target="$(detect_target)"
  asset="${BIN}-${target}.tar.gz"
  if [ "$version" = latest ]; then
    base="https://github.com/${REPO}/releases/latest/download"
  else
    # Release tags carry a `v`; accept the version with or without one.
    base="https://github.com/${REPO}/releases/download/v${version#v}"
  fi

  staging="$(mktemp -d "${TMPDIR:-/tmp}/${BIN}-install.XXXXXX")"
  pending=''
  # An interrupt exits rather than resuming, so the EXIT trap is the one place the cleanup runs — and it
  # covers the file staged in the install directory too, so a failure between staging and the rename
  # does not leave an executable dotfile on PATH.
  trap 'rm -rf "$staging"; [ -z "$pending" ] || rm -f "$pending"' EXIT
  # HUP too: dash runs no EXIT trap when killed by a signal it does not trap, and closing the terminal
  # mid-install sends HUP.
  trap 'exit 1' HUP INT TERM

  say "Downloading ${asset}"
  fetch "${base}/${asset}" "${staging}/${asset}"
  fetch "${base}/checksums.txt" "${staging}/checksums.txt"

  # The same verification `upgrade` performs, so the first install is held to the bar every later one
  # is. An archive the release publishes no checksum for is refused, not installed unverified.
  #
  # The two downloads above resolve `latest` independently, so a release landing between them pairs one
  # release's archive with the next one's checksums. That fails here rather than installing anything,
  # which is the outcome to want — but "checksum mismatch" on its own reads as a compromised download,
  # so the `latest` case says that re-running is the fix.
  retry=''
  [ "$version" != latest ] || retry='; if a new release landed mid-install, re-running installs it'
  expected="$(awk -v name="$asset" '$2 == name { print $1 }' "${staging}/checksums.txt")"
  [ -n "$expected" ] || fail "the release publishes no checksum for ${asset}${retry}"
  actual="$(sha256 "${staging}/${asset}")"
  [ "$actual" = "$expected" ] ||
    fail "checksum mismatch for ${asset} (expected ${expected}, got ${actual})${retry}"

  tar -xzf "${staging}/${asset}" -C "$staging"
  [ -f "${staging}/${BIN}" ] || fail "${asset} did not contain the expected ${BIN} executable"

  mkdir -p "$install_dir"
  # Staged inside the install directory so the final `mv` is a rename within one filesystem: atomic,
  # and safe over a copy of the command that is running right now. Created by `mktemp`, which refuses
  # an existing name, rather than at a predictable one: `cp` and `chmod` follow a symlink, so under
  # `sudo` into a group-writable directory a link planted at a guessable name would choose a file for
  # root to overwrite.
  pending="$(mktemp "${install_dir}/.${BIN}.install.XXXXXX")"
  cat "${staging}/${BIN}" >"$pending"
  chmod 755 "$pending"

  # Run before it replaces anything, so a build this machine cannot execute — a 32-bit userland on a
  # 64-bit kernel reports a 64-bit `uname -m` — fails here and leaves a working install untouched.
  installed="$("$pending" --version 2>/dev/null)" ||
    fail "the downloaded ${BIN} does not run on this machine ($(uname -s) $(uname -m)); nothing was changed"
  mv -f "$pending" "${install_dir}/${BIN}"
  pending=''

  say "Installed ${BIN}${installed:+ ${installed}} to ${install_dir}/${BIN}"
  setup_path "$install_dir"
}

# Prints a progress line on stderr, keeping stdout free for anything piping this script's output.
say() {
  printf '%s\n' "$*" >&2
}

# Reports a failure and stops.
fail() {
  printf 'error: %s\n' "$*" >&2
  exit 1
}

# Maps this machine onto the release asset suffix the release step packs: `<os>-<arch>`.
detect_target() {
  case "$(uname -s)" in
    Darwin) os=darwin ;;
    Linux) os=linux ;;
    *) fail "no ${BIN} release is published for $(uname -s); on Windows, download ${BIN}-windows-x64.zip from https://github.com/${REPO}/releases/latest" ;;
  esac
  case "$(uname -m)" in
    x86_64 | amd64) arch=x64 ;;
    arm64 | aarch64) arch=arm64 ;;
    *) fail "no ${BIN} release is published for $(uname -m)" ;;
  esac
  # A shell running under Rosetta reports x86_64 on Apple Silicon. The native build is the one to
  # install there: it is faster, and it does not stop working if Rosetta is removed.
  if [ "$os" = darwin ] && [ "$arch" = x64 ] && [ "$(sysctl -n sysctl.proc_translated 2>/dev/null || true)" = 1 ]; then
    arch=arm64
  fi
  # The Linux builds link against glibc, so on a musl system (Alpine) the executable would install
  # and then fail to start. Said up front instead.
  if [ "$os" = linux ] && ldd --version 2>&1 | grep -qi musl; then
    fail "the ${BIN} Linux release is built for glibc and does not run on musl; install the npm package instead"
  fi
  printf '%s-%s\n' "$os" "$arch"
}

# Downloads a URL to a file with curl, or wget where curl is missing. Fails on an HTTP error rather
# than saving the error page as the archive.
#
# Pinned to HTTPS, and `-L` is why that matters: the URL this is given is always `https://`, but a
# redirect decides the scheme of the *next* hop, so without the pin a redirect could walk the download
# down to plain HTTP and the checksum would then be verifying whatever that answered. `--proto '=https'`
# refuses any other scheme at any hop and `--tlsv1.2` sets a floor; `--https-only` is wget's spelling
# of the same thing. Both are long-standing options, so neither narrows which machines can install.
fetch() {
  if command -v curl >/dev/null 2>&1; then
    curl -fsSL --proto '=https' --tlsv1.2 --retry 3 -o "$2" "$1" || fail "could not download $1"
  elif command -v wget >/dev/null 2>&1; then
    wget -q --https-only -O "$2" "$1" || fail "could not download $1"
  else
    fail "curl or wget is required to download ${BIN}"
  fi
}

# SHA-256 of a file: `sha256sum` on Linux, `shasum` on macOS.
sha256() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | awk '{ print $1 }'
  elif command -v shasum >/dev/null 2>&1; then
    shasum -a 256 "$1" | awk '{ print $1 }'
  else
    fail "sha256sum or shasum is required to verify the download"
  fi
}

# Puts the install directory on PATH for every new shell when it is not on PATH already, so the command
# works by name straight after installing: one guarded line appended to the startup file of the user's
# shell, the way most `curl | sh` installers do it. When that is unwanted or unsafe, it says which check
# declined and what to do instead. When the directory is on PATH already, this only names any other copy
# of the command that would run instead of this one.
setup_path() {
  dir="$1"
  # A trailing slash names the same directory as a PATH entry without one, so it must not read as missing.
  while [ "${dir%/}" != "$dir" ] && [ "$dir" != / ]; do dir="${dir%/}"; done
  # The real location too, since that is what a line written by an earlier run names.
  real=''
  case "$dir" in /*) real="$(cd -P -- "$dir" 2>/dev/null && pwd -P)" || real='' ;; esac

  for entry in "$dir" "$real"; do
    [ -n "$entry" ] || continue
    case ":${PATH}:" in
      *":${entry}:"*)
        found="$(command -v "$BIN" 2>/dev/null || true)"
        if [ -n "$found" ] && [ "$found" != "${dir}/${BIN}" ] && [ "$found" != "${real}/${BIN}" ]; then
          say "note: ${found} comes first on PATH, so \`${BIN}\` still runs that copy"
        fi
        return 0
        ;;
    esac
  done

  shell_name="${SHELL:-}"
  shell_name="${shell_name##*/}"
  profile="$(shell_profile "$shell_name")"
  # `~/.profile` is read by login shells only, which a new terminal window is not on Linux; macOS
  # terminals open login shells, so a new one is enough there.
  reload='Open a new terminal'
  case "$profile" in */.profile) [ "$(uname -s)" = Darwin ] || reload='Log out and back in' ;; esac
  # Whether the directory itself is safe to put on PATH, decided before anything else so that the line is
  # never offered for pasting when it is not — whichever check ends up declining. `advice` replaces the
  # paste-ready line where pasting it would be wrong: a relative entry that follows the current
  # directory, a path a shell would parse, or a directory other accounts can change, where the line
  # would create the exposure these checks exist to prevent.
  unsafe=''
  advice=''
  entry=''
  # Root with another user's home directory — `sudo` keeps HOME on some systems, as do `su` and `doas` —
  # would find that user's startup file, and a root-owned line in it would outlive this install; that
  # user's directories would also all read as foreign to root. Who owns HOME decides it, not how root got
  # here: `sudo -i`, or a `sudo` that resets HOME to /root, leaves root in a home of its own, which is
  # treated like any other account, as is a container build.
  borrowed=''
  if [ "$(id -u)" = 0 ] && [ -n "${HOME:-}" ] &&
    [ -z "$(find "${HOME}/." -prune -user 0 -print 2>/dev/null)" ]; then
    borrowed=yes
  fi
  case "$dir" in
    /*) ;;
    *)
      unsafe='the path is relative'
      advice='Set GALAXY_INSTALL_DIR to an absolute path and run this script again.'
      ;;
  esac
  if [ -n "$unsafe" ]; then
    :
  elif [ -z "$real" ]; then
    unsafe="${dir} could not be resolved"
    advice='Check that the directory exists and that you can enter it.'
  elif ! entry="$(path_entry "$real")"; then
    unsafe="${real} holds a character that cannot be written safely into a startup file"
    advice='Install into a directory whose path holds only letters, digits and / . _ + @ -, or add it to PATH yourself, quoted for your shell.'
  elif [ -n "$borrowed" ]; then
    # Not judged, so no line is offered either; the advice below depends on why the script declined.
    :
  elif ! path_dir_is_private "$real"; then
    unsafe="${real}, or a directory above it, can be changed by another account"
    advice='Install into a directory only you can change instead, such as the default $HOME/.local/bin.'
  fi

  # Each check that declines names itself, so the user knows what to change.
  why=''
  if [ -n "${GALAXY_NO_MODIFY_PATH:-}" ]; then
    why='GALAXY_NO_MODIFY_PATH is set'
  elif [ -z "$profile" ]; then
    why="it does not know the startup file for ${shell_name:-your shell}"
  elif [ -n "$borrowed" ]; then
    why="it is running as root with another user's home directory"
  elif [ -n "$unsafe" ]; then
    why="$unsafe"
  fi
  # A directory root did not judge gets no line to paste. Only when root was the reason does running as
  # the home directory's owner get the line added; otherwise it only gets the directory checked.
  if [ -n "$borrowed" ] && [ -z "$advice" ]; then
    case "$why" in
      *'as root'*) advice='Run this script again as the owner of your home directory (without sudo, su or doas) to have it add the directory to PATH.' ;;
      *) advice='Run this script as the owner of your home directory (without sudo, su or doas) to have the directory checked.' ;;
    esac
    # Under the borrowed home, this run may have just created the directory as root, and then that re-run
    # could not install into it. Only there: a directory elsewhere, such as a system one under /opt, was
    # never the home owner's to give back. The owner's name comes from `ls` and the path is the checked
    # entry, so both print safely; an owner name outside the usual characters is left out rather than
    # printed into a command.
    owner="$(ls -ld "${HOME}/." 2>/dev/null | awk '{ print $3 }')"
    case "$owner" in '' | *[!abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789._-]*) owner='' ;; esac
    case "$entry" in '$HOME/'*) ;; *) owner='' ;; esac
    if [ -n "$owner" ] && [ -z "$(find "${real}/." -prune -user "$owner" -print 2>/dev/null)" ]; then
      advice="${advice} The directory belongs to root now, so first give it back with: sudo chown -R ${owner} \"${entry}\""
    fi
  fi

  # What to run in the current terminal, which no startup file reaches until the next shell starts. Built
  # from the checked entry, never the path as given, so a pasted or run line names what was verified.
  if [ "$shell_name" = fish ]; then
    now="set -gx PATH \"${entry}\" \$PATH"
  else
    now="export PATH=\"${entry}:\$PATH\""
  fi

  say ""
  if [ -z "$why" ]; then
    # The line names the real location: that is the path the checks above verified, so no symlink along
    # the given path can later be pointed somewhere else.
    line="$(path_line "$shell_name" "$entry")"
    # Matched on the exact line, so re-running the script adds nothing. stderr is redirected before the
    # append below so a file that cannot be opened fails quietly into the message after it.
    if grep -qsF -- "$line" "$profile"; then
      say "${profile} already puts ${dir} on PATH. ${reload}, or run this to use ${BIN} in this one:"
      say "  ${now}"
      return 0
    fi
    if mkdir -p "$(dirname "$profile")" 2>/dev/null &&
      printf '\n# Added by the %s installer\n%s\n' "$BIN" "$line" 2>/dev/null >>"$profile"; then
      say "Added ${dir} to PATH in ${profile}. ${reload}, or run this to use ${BIN} in this one:"
      say "  ${now}"
      return 0
    fi
    why="${profile} could not be written"
  fi

  say "${dir} is not on your PATH, and this script did not add it: ${why}."
  if [ -n "$advice" ]; then
    say "$advice"
  else
    say "Add it by appending this line to ${profile:-your shell profile}:"
    say "  ${now}"
  fi
}

# The startup file the user's shell reads in every new terminal, or nothing without a home directory to
# find it in. Bash on macOS opens login shells, which read only the first of `.bash_profile`,
# `.bash_login` and `.profile` that exists — creating `.bash_profile` beside an existing `.profile`
# would silently stop `.profile` being read — so it appends to whichever is there already. Fish gets a
# file of its own in `conf.d`, which it reads without any edit to the user's `config.fish`. A shell
# not listed here — csh, nu, xonsh, yash — reads none of these files and speaks another syntax, so it gets
# nothing and the line is only printed.
shell_profile() {
  [ -n "${HOME:-}" ] || return 0
  case "$1" in
    zsh)
      # A relative ZDOTDIR would name a file under whatever directory the script runs in.
      config="${ZDOTDIR:-}"
      case "$config" in /*) ;; *) config="$HOME" ;; esac
      printf '%s\n' "${config}/.zshrc"
      ;;
    fish)
      config="${XDG_CONFIG_HOME:-}"
      case "$config" in /*) ;; *) config="${HOME}/.config" ;; esac
      printf '%s\n' "${config}/fish/conf.d/${BIN}.fish"
      ;;
    bash)
      if [ "$(uname -s)" = Darwin ]; then
        for file in .bash_profile .bash_login .profile; do
          if [ -f "${HOME}/${file}" ]; then
            printf '%s\n' "${HOME}/${file}"
            return 0
          fi
        done
        printf '%s\n' "${HOME}/.bash_profile"
      else
        printf '%s\n' "${HOME}/.bashrc"
      fi
      ;;
    sh | dash | ash | ksh | mksh) printf '%s\n' "${HOME}/.profile" ;;
  esac
}

# The directory as the startup-file line spells it, or a failure when it cannot be written safely. The
# line runs in every shell the user opens from now on, so the directory must hold no colon, which would
# split it into two PATH entries, and the part written out literally must be made only of characters that
# mean nothing inside double quotes in sh or fish; anything else is printed for the user to add instead.
# Under the home directory it is written as `$HOME/...`, which the shell expands rather than parses, so
# the home directory itself is exempt from the allowlist and the line survives the home directory
# moving. Letters are spelled out because some locales collate ranges differently.
path_entry() {
  case "$1" in
    *:*) return 1 ;;
  esac
  literal="$1"
  prefix=''
  home="$(cd -P -- "${HOME:-/nonexistent}" 2>/dev/null && pwd -P)" || home=''
  if [ -n "$home" ] && [ "$home" != / ]; then
    case "$1" in
      "${home}"/*)
        literal="${1#"${home}"/}"
        prefix='$HOME/'
        ;;
    esac
  fi
  case "$literal" in
    *[!abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/._+@-]*) return 1 ;;
  esac
  printf '%s\n' "${prefix}${literal}"
}

# Whether a real (symlink-free) directory and every directory above it belong to the user or root and
# are closed to everyone else. The line puts the directory ahead of the system ones on PATH for good, so
# an account that could write into it, or rename it away inside a parent it can write to, could plant a
# `sudo` or `ls` the user then runs. That rules out anything under `/tmp` too: sticky or not, once a
# cleaner removes the directory any account can create it again. Group-writable is allowed because
# user-private groups make that the default on some distributions. A `find` that fails counts as not
# private, so the fallback is the printed line.
path_dir_is_private() {
  uid="$(id -u)" || return 1
  current="$1"
  while :; do
    trusted="$(find "${current}/." -prune \( -user "$uid" -o -user 0 \) ! -perm -0002 -print 2>/dev/null)" ||
      return 1
    [ -n "$trusted" ] || return 1
    [ "$current" != / ] || return 0
    current="$(dirname "$current")"
  done
}

# The line that puts a directory on PATH. It checks PATH first, so a nested shell, or a startup file read
# twice, does not stack up copies of the same entry.
path_line() {
  if [ "$1" = fish ]; then
    printf '%s\n' "contains -- \"${2}\" \$PATH; or set -gx PATH \"${2}\" \$PATH"
  else
    printf '%s\n' "case \":\${PATH}:\" in *\":${2}:\"*) ;; *) export PATH=\"${2}:\${PATH}\" ;; esac"
  fi
}

main "$@"
